//! Executor — a detached thread, a mailbox, and the engine state it
//! exclusively owns.
//!
//! This file is part of the pdf_manipulator host layer (NOT upstream).
//!
//! An executor is the native twin of a Web Worker. It is decision-free:
//! routing, pinning, queuing, and scheduling all live in the Dart Router.
//! The executor body does exactly one thing — pull jobs from
//! its mailbox and run them against its own `EngineState` through
//! `handle_request`.
//!
//! ## Ownership (the race-freedom contract)
//!
//! - `EngineState` is created ON the executor thread and dropped when the
//!   thread exits. No other code can ever reference it — teardown is
//!   a plain Rust drop, never a cross-thread free.
//! - The only cross-thread surfaces are small and single-purpose:
//!   the mailbox sender, the executor cancel flag, the cancel-flag map,
//!   and the I/O channel registry. Each is documented at its site.
//!
//! ## Terminate protocol (why no notify callback ever fires after a terminate)
//!
//! Terminating an executor or cancelling a job wakes parked I/O by taking each
//! channel's SyncPair mutex, setting FLAG_CANCELLED, and notifying.
//! Readers/writers hold that same mutex from request-write through
//! their notify call into the condvar wait. Therefore a terminate can only
//! land while the executor thread is parked (or absent) — never between
//! its cancel-flag re-check and its notify call. Once the terminate returns, the
//! executor thread will never invoke a Dart notify callback again, so the
//! caller may close NativeCallables immediately.

use crate::host::bridge_api::{handle_request, BoxedReader, BoxedWriter};
use crate::host::binary_codec::ResponseWriter;
use crate::host::heap;
use crate::host::engine_state::EngineState;
use crate::host::native::callback_reader::CallbackReader;
use crate::host::native::callback_writer::CallbackWriter;
use crate::host::native::cancel::CancelFlags;
use crate::host::native::shared_buffer::{self as sb, read_channel as rc, write_channel as wc};
use crossbeam_channel::Receiver;
use std::collections::HashMap;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

// ── Job — one operation, routed to exactly one executor ────────────────

/// A source channel descriptor: shared buffer + Dart notify callback.
pub struct SourceChannel {
    /// Address of the read-channel shared buffer (Dart-allocated).
    pub buf: usize,
    /// Dart NativeCallable listener pointer; None for absent slots.
    pub notify: Option<unsafe extern "C" fn()>,
    /// Source length in bytes.
    pub length: i64,
    /// Keep this channel registered after the job ends. Set for
    /// sources that a handle-creating op (open/edit) moves into the
    /// document — the channel then lives until the handle is released
    /// and must stay reachable by terminate/cancel wakes.
    pub keep: bool,
}

/// A sink channel descriptor: shared buffer + Dart notify callback.
pub struct SinkChannel {
    /// Address of the write-channel shared buffer (Dart-allocated).
    pub buf: usize,
    /// Dart NativeCallable listener pointer; None for absent slots.
    pub notify: Option<unsafe extern "C" fn()>,
}

/// One operation. Built by `executor_submit` from FFI arguments, consumed
/// once by the executor thread.
pub struct Job {
    /// Job identity, generated by the Dart Router (single-threaded —
    /// the one owner of job identity).
    pub job_id: u64,
    /// Binary-encoded request (op name + args).
    pub request: Vec<u8>,
    /// Indexed source channels.
    pub sources: Vec<SourceChannel>,
    /// Indexed sink channels.
    pub sinks: Vec<SinkChannel>,
    /// allo-isolate port for the result bytes.
    pub result_port: i64,
    /// This job's cancel flag (also held in the controller's cancel-flag
    /// map so `executor_job_cancel` can reach it).
    pub cancel: Arc<AtomicBool>,
}

/// What the executor thread takes from its mailbox, strictly one item at a
/// time: the mailbox may buffer a second job while one runs, but the
/// thread starts nothing until the item in hand has posted.
pub enum Mail {
    /// One operation.
    Job(Job),
    /// Replace the engine state with a fresh one. Accepted only while no
    /// job is outstanding (see `ExecutorController::admit_reset`), so the
    /// thread sees it between jobs.
    Reset {
        /// allo-isolate port that receives the answer.
        result_port: i64,
    },
}

// ── ChannelRegistry — live I/O buffers, woken on cancellation ──────

#[derive(Clone, Copy)]
enum ChannelKind {
    Read,
    Write,
}

/// Registry owner tag for held channels (alive for a handle's
/// lifetime, not currently adopted by any job). Real job ids come
/// from the Dart Router's counter and start at 1.
const HELD_OWNER: u64 = u64::MAX;

/// Registry of the I/O channels currently parked-or-parkable on this
/// executor. The executor thread registers a job's channels before building
/// readers/writers and unregisters them before posting the result —
/// so an address in here always points at live, Dart-owned memory
/// (Dart frees a job's buffers only after receiving its result).
///
/// Lock order: registry lock → channel pair mutex. The executor thread
/// never takes the registry lock while holding a pair mutex, so this
/// order cannot deadlock.
pub struct ChannelRegistry {
    entries: Mutex<HashMap<usize, (ChannelKind, u64)>>,
}

impl ChannelRegistry {
    /// Create an empty registry.
    pub fn new() -> Self {
        Self { entries: Mutex::new(HashMap::new()) }
    }

    /// Register a job's channels AND adopt every held channel on
    /// this executor under the job's id. Adoption is what makes per-job
    /// cancel instant even when the op parks inside a handle's held
    /// reader (created by an earlier job): executors run one job at a
    /// time, so any channel parked during this job belongs to it.
    fn register(&self, job: &Job) {
        let mut entries = self.entries.lock().unwrap();
        for (&buf, (kind, owner)) in entries.iter_mut() {
            if *owner == HELD_OWNER {
                *owner = job.job_id;
                // A cancel of an earlier job may have flagged this held
                // channel; this job starts with it live. The registry lock
                // orders the revival before any cancel of THIS job.
                unsafe { revive_channel(buf as *mut u8, *kind) };
            }
        }
        for s in &job.sources {
            if s.buf != 0 {
                entries.insert(s.buf, (ChannelKind::Read, job.job_id));
            }
        }
        for s in &job.sinks {
            if s.buf != 0 {
                entries.insert(s.buf, (ChannelKind::Write, job.job_id));
            }
        }
    }

    /// Undo `register` at job end: kept sources and adopted held
    /// channels park back under HELD_OWNER; everything else leaves
    /// the registry (Dart frees those buffers after the result).
    fn release_job(&self, job: &Job) {
        let mut entries = self.entries.lock().unwrap();
        for s in &job.sources {
            if !s.keep {
                entries.remove(&s.buf);
            }
        }
        for s in &job.sinks {
            entries.remove(&s.buf);
        }
        for (_, owner) in entries.values_mut() {
            if *owner == job.job_id {
                *owner = HELD_OWNER;
            }
        }
    }

    /// Remove one held channel (handle released). The caller frees
    /// the buffer only after this returns — never while registered.
    pub fn release_one(&self, buf: usize) {
        self.entries.lock().unwrap().remove(&buf);
    }

    /// Forget every held channel (the executor's state was reset, so no handle
    /// reads them any more). Only the executor thread calls this, between jobs,
    /// when every registered channel is a held one. The caller frees the
    /// buffers only after this returns.
    fn release_held(&self) {
        self.entries.lock().unwrap().retain(|_, (_, owner)| *owner != HELD_OWNER);
    }

    /// Wake every registered channel with FLAG_CANCELLED (executor terminate).
    pub fn cancel_all(&self) {
        let entries = self.entries.lock().unwrap();
        for (&buf, &(kind, _)) in entries.iter() {
            unsafe { cancel_channel(buf as *mut u8, kind) };
        }
    }

    /// Wake one job's registered channels with FLAG_CANCELLED.
    pub fn cancel_job(&self, job_id: u64) {
        let entries = self.entries.lock().unwrap();
        for (&buf, &(kind, owner)) in entries.iter() {
            if owner == job_id {
                unsafe { cancel_channel(buf as *mut u8, kind) };
            }
        }
    }

    /// Number of currently registered channels. Diagnostics and tests
    /// only — never used for decisions.
    pub fn live_count(&self) -> usize {
        self.entries.lock().unwrap().len()
    }
}

impl Default for ChannelRegistry {
    fn default() -> Self {
        Self::new()
    }
}

/// Set FLAG_CANCELLED and signal one channel, holding its pair mutex
/// throughout — the lock-ordering guarantee the terminate protocol rests on.
///
/// # Safety
/// `buf` must be a live channel buffer initialized via `sb::init_sync`.
unsafe fn cancel_channel(buf: *mut u8, kind: ChannelKind) {
    let (sync_offset, cancel_offset) = match kind {
        ChannelKind::Read => (rc::OFFSET_SYNC_PTR, rc::OFFSET_CANCEL),
        ChannelKind::Write => (wc::OFFSET_SYNC_PTR, wc::OFFSET_CANCEL),
    };
    let pair = sb::get_sync(buf, sync_offset);
    let _guard = pair.mutex.lock().unwrap();
    sb::set_cancelled(buf, cancel_offset);
    pair.condvar.notify_all();
}

/// Clear one channel's cancel word. Only the executor thread calls this, from
/// `ChannelRegistry::register`, for a channel no job owns.
///
/// # Safety
/// `buf` must be a live channel buffer.
unsafe fn revive_channel(buf: *mut u8, kind: ChannelKind) {
    let cancel_offset = match kind {
        ChannelKind::Read => rc::OFFSET_CANCEL,
        ChannelKind::Write => wc::OFFSET_CANCEL,
    };
    sb::clear_cancelled(buf, cancel_offset);
}

// ── ExecutorController — the cross-thread control surface ──────────────

/// Everything a caller of terminate or submit may touch from outside the executor
/// thread. Held in the global executor table behind an Arc; the executor
/// thread holds its own clone so the controller outlives a racing
/// table removal.
pub struct ExecutorController {
    /// Intake. `None` after terminate — the executor thread answers what is left
    /// in it cancelled and exits when the sender is gone.
    pub(crate) mailbox: Mutex<Option<crossbeam_channel::Sender<Mail>>>,
    /// Executor-wide terminate flag. Set once by `executor_terminate`, never cleared.
    pub cancel: Arc<AtomicBool>,
    /// Live I/O channels for wake-on-cancel.
    pub channels: ChannelRegistry,
    /// job_id → job cancel flag, for `executor_job_cancel`. Inserted at
    /// submit (before enqueue, so a cancel can always find its job),
    /// removed by the executor thread when the job finishes.
    pub(crate) cancel_flags: Mutex<HashMap<u64, Arc<AtomicBool>>>,
    /// The job the executor thread is executing now, `None` while it is idle
    /// or has not dequeued the next one. Lets a cancel tell a queued job
    /// from a running one.
    pub(crate) running: Mutex<Option<u64>>,
    /// Set once by the executor thread, BEFORE it posts the result of the job
    /// whose engine panicked: a panic makes the executor dead, and the host reads
    /// this flag when that post arrives.
    pub dead: AtomicBool,
    /// The lease whose messages the executor serves; 0 before the first
    /// `begin_lease`. Written only while `cancel_flags` is locked, so a check
    /// of it under that lock is exact.
    lease: AtomicU64,
    /// The last lease handed out. Ids count up from 1 and are never reused.
    last_lease: AtomicU64,
    /// The most bytes the executor thread has held since its last reset, as of
    /// the last job it finished or reset it ran. Stored before the answer is
    /// posted, so the host reads it after the answer.
    heap_peak: AtomicUsize,
}

impl ExecutorController {
    /// A controller for an executor that has accepted no job yet.
    pub(crate) fn new(sender: crossbeam_channel::Sender<Mail>) -> Self {
        Self {
            mailbox: Mutex::new(Some(sender)),
            cancel: Arc::new(AtomicBool::new(false)),
            channels: ChannelRegistry::new(),
            cancel_flags: Mutex::new(HashMap::new()),
            running: Mutex::new(None),
            dead: AtomicBool::new(false),
            lease: AtomicU64::new(0),
            last_lease: AtomicU64::new(0),
            heap_peak: AtomicUsize::new(0),
        }
    }

    /// The executor's peak heap since its last reset; see the field.
    pub fn heap_peak(&self) -> usize {
        self.heap_peak.load(Ordering::SeqCst)
    }

    /// Start a new lease on this executor and make it the current one: every
    /// message that carries an older lease is dropped from now on. Returns
    /// `None`, changing nothing, while a job is outstanding, while a held
    /// channel is still registered, or after the engine panicked: a lease
    /// changes hands only on an idle, live executor that holds nothing, which
    /// is what a reset leaves. The earlier lease then has no channel whose
    /// release it could still owe.
    pub fn begin_lease(&self) -> Option<u64> {
        let cancel_flags = self.cancel_flags.lock().unwrap();
        if !cancel_flags.is_empty()
            || self.channels.live_count() != 0
            || self.dead.load(Ordering::SeqCst)
        {
            return None;
        }
        let lease = self.last_lease.fetch_add(1, Ordering::SeqCst) + 1;
        self.lease.store(lease, Ordering::SeqCst);
        Some(lease)
    }

    /// Register a job's cancel flag when `lease` is the current lease, else leave
    /// the executor untouched and return the refusal to post.
    pub(crate) fn admit_job(&self, lease: u64, job: &Job) -> Result<(), &'static str> {
        let mut cancel_flags = self.cancel_flags.lock().unwrap();
        if self.lease.load(Ordering::SeqCst) != lease {
            return Err(STALE_LEASE_MESSAGE);
        }
        cancel_flags.insert(job.job_id, job.cancel.clone());
        Ok(())
    }

    /// Queue a reset when `lease` is current, the executor is alive and no job
    /// is outstanding, queued or running. The lock on `cancel_flags` is held
    /// through the enqueue, so no job can be filed between the check and
    /// the reset.
    pub(crate) fn request_reset(&self, lease: u64, result_port: i64) -> Result<(), &'static str> {
        let cancel_flags = self.cancel_flags.lock().unwrap();
        if self.lease.load(Ordering::SeqCst) != lease {
            return Err(STALE_LEASE_MESSAGE);
        }
        if self.dead.load(Ordering::SeqCst) {
            return Err(ENGINE_DEAD_MESSAGE);
        }
        if !cancel_flags.is_empty() {
            return Err(EXECUTOR_BUSY_MESSAGE);
        }
        match self.mailbox.lock().unwrap().as_ref() {
            Some(sender) if sender.send(Mail::Reset { result_port }).is_ok() => Ok(()),
            _ => Err(ENGINE_DEAD_MESSAGE),
        }
    }

    /// Whether `lease` is the lease the executor serves.
    pub(crate) fn is_current(&self, lease: u64) -> bool {
        self.lease.load(Ordering::SeqCst) == lease
    }

    /// Cancel one job. Returns true when the job had not started, so the
    /// executor will skip it without touching the engine. A cancel under a
    /// lease that is not current changes nothing and returns false: the
    /// job ids of two leases come from two counters and may collide.
    ///
    /// `running` is held across the flag store: the executor thread marks a job
    /// running before it reads the job's flag, so every cancel either
    /// lands first (the executor skips the job) or finds it running (its I/O
    /// is woken below).
    pub fn cancel_job(&self, lease: u64, job_id: u64) -> bool {
        let running = self.running.lock().unwrap();
        let cancel_flags = self.cancel_flags.lock().unwrap();
        if self.lease.load(Ordering::SeqCst) != lease {
            return false;
        }
        let Some(flag) = cancel_flags.get(&job_id).cloned() else {
            return false;
        };
        drop(cancel_flags);
        flag.store(true, Ordering::SeqCst);
        let queued = *running != Some(job_id);
        self.channels.cancel_job(job_id);
        queued
    }
}

/// Error every job posts that reaches an executor after its engine panicked.
pub const ENGINE_DEAD_MESSAGE: &str = "the engine stopped after an operation panicked";

/// Error a job, or a reset, posts when its lease is not the executor's current
/// one. The message is dropped without touching the engine.
pub const STALE_LEASE_MESSAGE: &str = "the executor's lease was replaced; this message is stale";

/// Error a reset posts when a job is still outstanding on the executor.
pub const EXECUTOR_BUSY_MESSAGE: &str = "the executor cannot reset while a job is outstanding";

// ── The executor body ───────────────────────────────────────────────────

/// The executor thread's main loop. Creates the executor's state, drains the
/// mailbox, exits when the sender is dropped (terminate or shutdown).
///
/// A panic in the engine ends the executor's service: its state is dropped,
/// the mailbox is closed to new jobs, and every job already queued posts
/// an error. The thread lives on only until the last sender is gone, so a
/// job racing the close still gets its one post.
///
/// Budget-slot release is NOT done here — the executor table wraps this
/// call in an RAII guard where the thread starts, so the slot is returned
/// even if this thread unwinds.
pub fn executor_main(mailbox: Receiver<Mail>, controller: Arc<ExecutorController>) {
    let mut state = Some(EngineState::new());

    while let Ok(mail) = mailbox.recv() {
        match mail {
            Mail::Job(job) => {
                heap::adopt(submitted_bytes(&job));
                match state.as_mut() {
                    Some(live) => {
                        if !run_job(live, &controller, job) {
                            state = None;
                            *controller.mailbox.lock().unwrap() = None;
                        }
                    }
                    None => fail_job(&controller, job),
                }
            }
            Mail::Reset { result_port } => {
                let answer = match state.as_mut() {
                    // Dequeued after a terminate: the executor is going away, and
                    // the engine state with it.
                    Some(_) if controller.cancel.load(Ordering::SeqCst) => {
                        ResponseWriter::cancelled()
                    }
                    Some(live) => {
                        reset_executor(live, &controller);
                        ResponseWriter::ok().finish()
                    }
                    None => ResponseWriter::error(ENGINE_DEAD_MESSAGE),
                };
                post_result(result_port, answer);
            }
        }
    }

    // Mailbox closed: the executor is dead. `state` drops here, freeing
    // every handle this executor owned — on this thread, the only thread
    // that ever touched it.
}

/// Replace the executor's engine state with a fresh one and forget the held
/// channels that belonged to it. Runs between jobs on the executor thread, so
/// no reader is parked on a channel and no other thread touches the state.
/// Dart frees the held buffers after the reset's answer, never before.
pub(crate) fn reset_executor(state: &mut EngineState, controller: &ExecutorController) {
    *state = EngineState::new();
    controller.channels.release_held();
    heap::reset_peak();
    controller.heap_peak.store(heap::peak(), Ordering::SeqCst);
}

/// What the Arc of a job's cancel flag takes: two counts and the flag, padded
/// to a word.
const CANCEL_ARC_BYTES: usize = 3 * std::mem::size_of::<usize>();

/// What `executor_submit` allocated for `job` on the caller's thread and this
/// thread frees: the request, the two channel lists and the cancel flag's Arc.
fn submitted_bytes(job: &Job) -> usize {
    job.request.capacity()
        + job.sources.capacity() * std::mem::size_of::<SourceChannel>()
        + job.sinks.capacity() * std::mem::size_of::<SinkChannel>()
        + CANCEL_ARC_BYTES
}

/// Post the executor-dead error for a job that arrives after a panic.
fn fail_job(controller: &ExecutorController, job: Job) {
    post_result(job.result_port, ResponseWriter::error(ENGINE_DEAD_MESSAGE));
    controller.cancel_flags.lock().unwrap().remove(&job.job_id);
}

/// What a finished job posts, and whether the executor survives it.
///
/// A success is never rewritten, cancel or not: an op that creates a handle
/// and finishes in the same window as its cancel has already put a
/// document in the executor, and only the Router, which names the handle,
/// can dispose it. A non-success cannot hold a handle, so a cancel that
/// landed mid-op makes the engine's I/O error read as the typed cancelled
/// status, identical to a pre-dequeue cancel. A panic is reported as a
/// panic and ends the executor.
fn outcome(result: std::thread::Result<Vec<u8>>, cancelled: bool) -> (Vec<u8>, bool) {
    match result {
        Ok(bytes) if bytes.first() == Some(&1) => (bytes, true),
        Ok(_) if cancelled => (ResponseWriter::cancelled(), true),
        Ok(bytes) => (bytes, true),
        Err(_) => (
            ResponseWriter::error("internal error: engine operation panicked"),
            false,
        ),
    }
}

/// Execute one job against the executor's state and post the result. Returns
/// false when the engine panicked and the executor must stop serving.
fn run_job(state: &mut EngineState, controller: &ExecutorController, job: Job) -> bool {
    // Marked before the job's flag is read, so a cancel either lands first
    // (and the job is skipped) or finds the job running; see `cancel_job`.
    *controller.running.lock().unwrap() = Some(job.job_id);

    // Dequeued after a terminate or a per-job cancel: the notify callbacks
    // may be dead and the buffers may be gone. Touch neither. The
    // Dart Router already resolved this job's task as cancelled (it
    // owns completion after terminate); this post is a harmless no-op if
    // the port is closed.
    if controller.cancel.load(Ordering::SeqCst) || job.cancel.load(Ordering::SeqCst) {
        post_result(job.result_port, ResponseWriter::cancelled());
        controller.cancel_flags.lock().unwrap().remove(&job.job_id);
        *controller.running.lock().unwrap() = None;
        return true;
    }

    // Register channels BEFORE constructing readers/writers. The
    // registry mutex orders this against cancel_all/cancel_job: a
    // registration that lands after a cancel is guaranteed to see the
    // cancel flag at the reader's first I/O check.
    controller.channels.register(&job);

    let token = CancelFlags::new(controller.cancel.clone(), job.cancel.clone());

    // Engine ops return Result for every expected failure; a panic
    // here is a bug in the engine. Catching it keeps the executor (and
    // every other handle on it) alive, at the cost of this one job.
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut sources = Vec::with_capacity(job.sources.len());
        // An empty source stays in the list: dropping it would shift every
        // later source's index, and the op must see the empty input to
        // refuse it as a corrupt file.
        for s in &job.sources {
            if s.buf != 0 && s.notify.is_some() {
                let reader = unsafe {
                    CallbackReader::new(
                        s.buf as *mut u8,
                        s.notify.unwrap(),
                        s.length as u64,
                        token.clone(),
                    )
                };
                sources.push(BoxedReader(Box::new(reader)));
            }
        }

        let mut sinks = Vec::with_capacity(job.sinks.len());
        for s in &job.sinks {
            if s.buf != 0 && s.notify.is_some() {
                let writer = unsafe {
                    CallbackWriter::new(s.buf as *mut u8, s.notify.unwrap(), token.clone())
                };
                sinks.push(BoxedWriter::buffered(writer));
            }
        }

        handle_request(state, &job.request, None, sources, sinks, &token.check())
    }));

    // Release BEFORE posting: the post triggers Dart's buffer free
    // for non-kept channels, which must never race a canceller
    // walking the registry. Kept + adopted channels return to HELD.
    controller.channels.release_job(&job);
    controller.cancel_flags.lock().unwrap().remove(&job.job_id);

    // The flags are set-once, so this check cannot misfire on a job that
    // finished normally.
    let was_cancelled = controller.cancel.load(Ordering::SeqCst)
        || job.cancel.load(Ordering::SeqCst);

    let (bytes, survives) = outcome(result, was_cancelled);
    if !survives {
        controller.dead.store(true, Ordering::SeqCst);
    }
    *controller.running.lock().unwrap() = None;
    controller.heap_peak.store(heap::peak(), Ordering::SeqCst);
    post_result(job.result_port, bytes);
    survives
}

/// Post result bytes to the job's Dart port. A closed port (job
/// cancelled, instance disposed) makes this a safe no-op.
///
/// A posted, non-empty response is shrunk to its length and boxed (a `Vec`
/// header) by allo-isolate on this thread, and freed by Dart's finalizer on a
/// Dart thread, so this thread stops counting those bytes before the post. A
/// post that fails frees them here, inside the call: they are counted again
/// afterwards, so the free nets to nothing.
pub(crate) fn post_result(port: i64, bytes: Vec<u8>) {
    let handed = if bytes.is_empty() { 0 } else { bytes.len() + std::mem::size_of::<Vec<u8>>() };
    heap::release(handed);
    let isolate = allo_isolate::Isolate::new(port);
    if !isolate.post(allo_isolate::ZeroCopyBuffer(bytes)) {
        heap::adopt(handed);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    unsafe extern "C" fn noop_notify() {}

    fn read_buf() -> Vec<u8> {
        let mut buf = vec![0u8; rc::TOTAL_SIZE];
        unsafe { sb::init_sync(buf.as_mut_ptr(), rc::OFFSET_SYNC_PTR) };
        buf
    }

    fn job_with_source(job_id: u64, buf: &mut [u8], keep: bool) -> Job {
        Job {
            job_id,
            request: vec![],
            sources: vec![SourceChannel {
                buf: buf.as_mut_ptr() as usize,
                notify: Some(noop_notify),
                length: 1024,
                keep,
            }],
            sinks: vec![],
            result_port: 0,
            cancel: Arc::new(AtomicBool::new(false)),
        }
    }

    /// What `executor_submit` builds on the caller's thread is what the executor
    /// adopts: the caller's heap grows by exactly `submitted_bytes`.
    #[test]
    fn a_submitted_job_is_adopted_at_the_size_the_caller_allocated() {
        let (mut buf, mut other) = (read_buf(), read_buf());
        let before = heap::live();
        let request = vec![7u8; 1000];
        let sources = vec![
            SourceChannel { buf: buf.as_mut_ptr() as usize, notify: None, length: 1, keep: false },
            SourceChannel { buf: other.as_mut_ptr() as usize, notify: None, length: 1, keep: false },
        ];
        let sinks = vec![SinkChannel { buf: 0, notify: None }];
        let job = Job {
            job_id: 1,
            request,
            sources,
            sinks,
            result_port: 0,
            cancel: Arc::new(AtomicBool::new(false)),
        };
        assert_eq!(heap::live() - before, submitted_bytes(&job));
        unsafe {
            sb::destroy_sync(buf.as_mut_ptr(), rc::OFFSET_SYNC_PTR);
            sb::destroy_sync(other.as_mut_ptr(), rc::OFFSET_SYNC_PTR);
        }
    }

    #[test]
    fn kept_channel_survives_job_and_is_adopted_by_the_next() {
        let registry = ChannelRegistry::new();
        let mut buf = read_buf();

        // Job 1 keeps its source: after release it parks under HELD.
        let job1 = job_with_source(1, &mut buf, true);
        registry.register(&job1);
        registry.release_job(&job1);
        assert_eq!(registry.live_count(), 1);

        // A cancel for a FINISHED job must not touch the held channel.
        registry.cancel_job(1);
        assert!(!sb::is_cancelled(buf.as_ptr(), rc::OFFSET_CANCEL));

        // Job 2 (no channels of its own) adopts the held channel —
        // cancelling job 2 now wakes the held reader it may be
        // parked in. This is the held-reader cancellation guarantee.
        let job2 = Job {
            job_id: 2,
            request: vec![],
            sources: vec![],
            sinks: vec![],
            result_port: 0,
            cancel: Arc::new(AtomicBool::new(false)),
        };
        registry.register(&job2);
        registry.cancel_job(2);
        assert!(sb::is_cancelled(buf.as_ptr(), rc::OFFSET_CANCEL));

        // After job 2 the channel parks back under HELD...
        registry.release_job(&job2);
        assert_eq!(registry.live_count(), 1);

        // ...until the handle is released — then it leaves for good.
        registry.release_one(buf.as_ptr() as usize);
        assert_eq!(registry.live_count(), 0);

        unsafe { sb::destroy_sync(buf.as_mut_ptr(), rc::OFFSET_SYNC_PTR) };
    }

    #[test]
    fn non_kept_channels_leave_the_registry_at_job_end() {
        let registry = ChannelRegistry::new();
        let mut buf = read_buf();

        let job = job_with_source(5, &mut buf, false);
        registry.register(&job);
        assert_eq!(registry.live_count(), 1);
        registry.release_job(&job);
        assert_eq!(registry.live_count(), 0);

        unsafe { sb::destroy_sync(buf.as_mut_ptr(), rc::OFFSET_SYNC_PTR) };
    }

    #[test]
    fn a_job_revives_the_held_channel_a_finished_jobs_cancel_flagged() {
        let registry = ChannelRegistry::new();
        let mut buf = read_buf();

        let job1 = job_with_source(1, &mut buf, true);
        registry.register(&job1);
        // Job 1 is cancelled while it runs: its held channel is flagged.
        registry.cancel_job(1);
        assert!(sb::is_cancelled(buf.as_ptr(), rc::OFFSET_CANCEL));
        registry.release_job(&job1);

        // Job 2 adopts the held channel and must find it live.
        let job2 = Job {
            job_id: 2,
            request: vec![],
            sources: vec![],
            sinks: vec![],
            result_port: 0,
            cancel: Arc::new(AtomicBool::new(false)),
        };
        registry.register(&job2);
        assert!(!sb::is_cancelled(buf.as_ptr(), rc::OFFSET_CANCEL));

        // A cancel of job 2 still wakes it, after the revival.
        registry.cancel_job(2);
        assert!(sb::is_cancelled(buf.as_ptr(), rc::OFFSET_CANCEL));

        unsafe { sb::destroy_sync(buf.as_mut_ptr(), rc::OFFSET_SYNC_PTR) };
    }

    #[test]
    fn a_success_is_never_rewritten_by_a_cancel() {
        let created = ResponseWriter::ok().finish();
        let (bytes, survives) = outcome(Ok(created.clone()), true);
        assert_eq!(bytes, created);
        assert!(survives);
    }

    #[test]
    fn a_failure_after_a_cancel_reads_as_cancelled() {
        let (bytes, survives) = outcome(Ok(ResponseWriter::error("host read failed")), true);
        assert_eq!(bytes, ResponseWriter::cancelled());
        assert!(survives);

        let failure = ResponseWriter::error("not found");
        assert_eq!(outcome(Ok(failure.clone()), false).0, failure);
    }

    #[test]
    fn a_panic_is_reported_and_ends_the_executor_even_when_cancelled() {
        let panicked = std::panic::catch_unwind(|| -> Vec<u8> { panic!("engine bug") });
        let (bytes, survives) = outcome(panicked, true);
        assert_eq!(bytes, ResponseWriter::error("internal error: engine operation panicked"));
        assert!(!survives);
    }

    #[test]
    fn a_cancel_tells_a_queued_job_from_a_running_one() {
        let (sender, _receiver) = crossbeam_channel::unbounded::<Mail>();
        let controller = ExecutorController::new(sender);
        let lease = controller.begin_lease().unwrap();
        for id in [1, 2] {
            controller.cancel_flags.lock().unwrap().insert(id, Arc::new(AtomicBool::new(false)));
        }
        *controller.running.lock().unwrap() = Some(1);

        assert!(!controller.cancel_job(lease, 1), "job 1 is running");
        assert!(controller.cancel_job(lease, 2), "job 2 has not started");
        assert!(!controller.cancel_job(lease, 3), "job 3 is unknown, or already finished");
        assert!(controller.cancel_flags.lock().unwrap()[&2].load(Ordering::SeqCst));
    }

    fn bare_job(job_id: u64) -> Job {
        Job {
            job_id,
            request: vec![],
            sources: vec![],
            sinks: vec![],
            result_port: 0,
            cancel: Arc::new(AtomicBool::new(false)),
        }
    }

    #[test]
    fn leases_count_up_from_one_and_start_only_on_an_idle_live_executor() {
        let (sender, _receiver) = crossbeam_channel::unbounded::<Mail>();
        let controller = ExecutorController::new(sender);
        assert_eq!(controller.begin_lease(), Some(1));
        assert_eq!(controller.begin_lease(), Some(2));
        assert!(controller.is_current(2));
        assert!(!controller.is_current(1));

        let job = bare_job(1);
        controller.admit_job(2, &job).unwrap();
        assert_eq!(controller.begin_lease(), None, "a job is outstanding");
        assert!(controller.is_current(2), "a refused begin changes nothing");
        controller.cancel_flags.lock().unwrap().remove(&1);

        let mut buf = read_buf();
        let kept = job_with_source(1, &mut buf, true);
        controller.channels.register(&kept);
        controller.channels.release_job(&kept);
        assert_eq!(controller.begin_lease(), None, "a held channel is still registered");
        controller.channels.release_held();
        assert_eq!(controller.begin_lease(), Some(3));
        unsafe { sb::destroy_sync(buf.as_mut_ptr(), rc::OFFSET_SYNC_PTR) };

        controller.dead.store(true, Ordering::SeqCst);
        assert_eq!(controller.begin_lease(), None, "a dead executor is never leased again");
    }

    #[test]
    fn a_job_under_a_stale_lease_is_refused_and_files_no_ticket() {
        let (sender, _receiver) = crossbeam_channel::unbounded::<Mail>();
        let controller = ExecutorController::new(sender);
        let first = controller.begin_lease().unwrap();
        let second = controller.begin_lease().unwrap();

        assert_eq!(controller.admit_job(first, &bare_job(1)), Err(STALE_LEASE_MESSAGE));
        assert!(controller.cancel_flags.lock().unwrap().is_empty());
        assert_eq!(controller.admit_job(second, &bare_job(1)), Ok(()));
        assert_eq!(controller.cancel_flags.lock().unwrap().len(), 1);
    }

    #[test]
    fn a_cancel_under_a_stale_lease_never_reaches_the_current_job() {
        // Two leases count their job ids separately, so the stale cancel
        // names a job id the current lease also holds.
        let (sender, _receiver) = crossbeam_channel::unbounded::<Mail>();
        let controller = ExecutorController::new(sender);
        let stale = controller.begin_lease().unwrap();
        let current = controller.begin_lease().unwrap();
        let job = bare_job(1);
        controller.admit_job(current, &job).unwrap();

        assert!(!controller.cancel_job(stale, 1));
        assert!(!job.cancel.load(Ordering::SeqCst), "the stale cancel flagged the job");

        controller.cancel_job(current, 1);
        assert!(job.cancel.load(Ordering::SeqCst));
    }

    #[test]
    fn a_reset_is_queued_only_for_the_current_lease_on_an_idle_live_executor() {
        let (sender, receiver) = crossbeam_channel::unbounded::<Mail>();
        let controller = ExecutorController::new(sender);
        let stale = controller.begin_lease().unwrap();
        let current = controller.begin_lease().unwrap();

        assert_eq!(controller.request_reset(stale, 7), Err(STALE_LEASE_MESSAGE));
        assert!(receiver.try_recv().is_err(), "a stale reset reached the mailbox");

        let job = bare_job(1);
        controller.admit_job(current, &job).unwrap();
        assert_eq!(controller.request_reset(current, 7), Err(EXECUTOR_BUSY_MESSAGE));
        assert!(receiver.try_recv().is_err(), "a reset behind a running job was queued");
        controller.cancel_flags.lock().unwrap().remove(&1);

        // An idle executor resets, and resets again.
        for _ in 0..2 {
            assert_eq!(controller.request_reset(current, 7), Ok(()));
            assert!(matches!(receiver.try_recv(), Ok(Mail::Reset { result_port: 7 })));
        }

        controller.dead.store(true, Ordering::SeqCst);
        assert_eq!(controller.request_reset(current, 7), Err(ENGINE_DEAD_MESSAGE));
    }

    #[test]
    fn a_reset_forgets_every_held_channel_and_keeps_a_jobs_own() {
        let registry = ChannelRegistry::new();
        let mut held = read_buf();
        let mut running = read_buf();

        let kept = job_with_source(1, &mut held, true);
        registry.register(&kept);
        registry.release_job(&kept);
        assert_eq!(registry.live_count(), 1);

        // Between jobs only held channels exist: all of them go.
        registry.release_held();
        assert_eq!(registry.live_count(), 0);

        // Job-owned entries are not held ones and stay.
        let job = job_with_source(2, &mut running, false);
        registry.register(&job);
        registry.release_held();
        assert_eq!(registry.live_count(), 1);
        registry.release_job(&job);

        unsafe {
            sb::destroy_sync(held.as_mut_ptr(), rc::OFFSET_SYNC_PTR);
            sb::destroy_sync(running.as_mut_ptr(), rc::OFFSET_SYNC_PTR);
        }
    }
}
